package com.dmoniak.patches.silt

import java.io.ByteArrayInputStream
import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.util.Base64
import java.util.zip.GZIPInputStream

/**
 * Binary diff patches to cleanly reconstruct the official DRM-free native ARM64
 * libil2cpp.so and libunity.so from the Google Play PairIP encrypted binaries.
 *
 * This restores the exact byte-for-byte official clean binaries, eliminating all
 * encrypted metadata, missing method specs (crash at 0xc351bc in il2cpp_init),
 * and MurmurHash SIGILL (at 0xc43a74 in libunity.so) on Android 16 / Xiaomi HyperOS.
 */
internal object SiltNativeDiffs {
    const val CLEAN_IL2CPP_ARM64_SIZE = 70232080
    const val PLAY_IL2CPP_ARM64_SIZE = 70273264

    const val CLEAN_UNITY_ARM64_SIZE = 26859520
    const val PLAY_UNITY_ARM64_SIZE = 26888480

    fun applyDiffPatch(source: ByteArray, patchGzipBytes: ByteArray): ByteArray {
        val patchStream = GZIPInputStream(ByteArrayInputStream(patchGzipBytes))
        val patchBytes = patchStream.readBytes()
        val buf = ByteBuffer.wrap(patchBytes).order(ByteOrder.LITTLE_ENDIAN)
        val chunkCount = buf.int
        val targetLen = buf.int
        val result = ByteArray(targetLen)
        val copyLen = minOf(source.size, targetLen)
        System.arraycopy(source, 0, result, 0, copyLen)
        for (i in 0 until chunkCount) {
            val off = buf.int
            val clen = buf.int
            buf.get(result, off, clen)
        }
        return result
    }

    fun getIl2CppArm64DiffBytes(): ByteArray {
        val fullB64 = IL2CPP_ARM64_PARTS.joinToString("")
        return Base64.getDecoder().decode(fullB64)
    }

    fun getUnityArm64DiffBytes(): ByteArray {
        val fullB64 = UNITY_ARM64_PARTS.joinToString("")
        return Base64.getDecoder().decode(fullB64)
    }

    private val IL2CPP_ARM64_PARTS = listOf(
        "",
        "",
        "",
        "",
        "",
    )

    private val UNITY_ARM64_PARTS = listOf(
        "",
        "",
        "",
    )
}
